import 'package:audioplayers/audioplayers.dart';

/// Game sound effects. Files ship in assets/sounds/ and are generated by
/// tool/generate_sounds.dart, so the repo needs no binary audio blobs.
class AudioService {
  AudioPlayer? _sfx;
  bool enabled = true;

  AudioPlayer get _player => _sfx ??= AudioPlayer(playerId: 'sfx');

  static const String _base = 'sounds';

  Future<void> preload() async {
    // audioplayers streams from assets on demand; nothing to pre-warm, but
    // warming the player pool avoids first-tap latency.
    await _player.setReleaseMode(ReleaseMode.stop);
  }

  Future<void> _play(String file, {double volume = 1}) async {
    if (!enabled) return;
    try {
      await _player.stop();
      await _player.play(AssetSource('$_base/$file'), volume: volume);
    } catch (_) {
      // Audio must never crash gameplay (e.g. missing file on a custom build).
    }
  }

  Future<void> whoosh() => _play('whoosh.wav', volume: 0.7);

  Future<void> buzz() => _play('buzz.wav', volume: 0.8);

  Future<void> win() => _play('win.wav');

  Future<void> click() => _play('click.wav', volume: 0.5);

  Future<void> coin() => _play('coin.wav', volume: 0.7);

  Future<void> heartLost() => _play('heart.wav', volume: 0.7);

  Future<void> dispose() async {
    await _sfx?.dispose();
    _sfx = null;
  }
}
